/// The software AK ed25519 public key = the tail 32 bytes of the ed25519 sk
/// (ed25519-compact secret keys are seed(32)||pubkey(32)).
pub fn ak_ed_pk() -> [u8; 32] {
    let mut p = [0u8; 32];
    p.copy_from_slice(&ak_ed_sk()[32..64]);
    p
}

/// Borrow the AK ed25519 private key (single addressable instance).
#[inline]
pub fn ak_ed_sk() -> &'static [u8; 64] {
    unsafe { &*core::ptr::addr_of!(AK_ED25519_SK) }
}
/// Borrow the AK SLH-DSA private key.
#[inline]
pub fn ak_slh_sk() -> &'static [u8; 64] {
    unsafe { &*core::ptr::addr_of!(AK_SLHDSA_SK) }
}

/// Zero the AK private keys in RAM. Call ONCE, AFTER all AK signing (the boot
/// quote and the ephemeral-key cert) — the AK then cannot be recovered by
/// anything that later reads HBoot's memory. The ephemeral key the kernel holds
/// is AK-certified but distinct, so runtime attestation continues to work.
pub fn scrub() {
    unsafe {
        core::ptr::write_bytes(core::ptr::addr_of_mut!(AK_ED25519_SK) as *mut u8, 0, 64);
        core::ptr::write_bytes(core::ptr::addr_of_mut!(AK_SLHDSA_SK) as *mut u8, 0, 64);
        core::arch::asm!("dsb sy");
    }
}
